using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace Society.Api;
public record DomainWrite(string Host);
public record SubscriptionWrite(string Plan,string State,int ChapterLimit,int MembershipLimit,long StorageLimit,string[] Features,DateTimeOffset? EndsAt,int Revision);
public record TenantStatusWrite(string Status,string Reason);
public class PlatformPolicy(AppDb db,IConfiguration config,IHostEnvironment env,IHttpClientFactory clients){
 public static readonly string[] Modules=["membership","community","communications","finance","studio","service","intelligence"];
 public static string Host(string value){var host=value.Trim().TrimEnd('.').ToLowerInvariant();if(host.Length is <4 or >253||!Regex.IsMatch(host,@"^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$")||System.Net.IPAddress.TryParse(host,out _)||host.EndsWith(".localhost")||host.EndsWith(".local"))throw new DomainException("Use a public fully-qualified DNS hostname without scheme, path or port");return host;}
 public async Task<TenantDomain?> Resolve(string host)=>await db.Set<TenantDomain>().AsNoTracking().SingleOrDefaultAsync(d=>d.Host==host.ToLowerInvariant()&&d.Status=="Verified"&&db.Tenants.Any(t=>t.Id==d.TenantId&&t.Status=="Active"));
 public async Task Enforce(Guid tenant,string module,HttpContext context){var bound=await Resolve(context.Request.Host.Host);if(bound!=null&&bound.TenantId!=tenant)throw new AccessDeniedException();var subscription=await db.Set<TenantSubscription>().AsNoTracking().SingleOrDefaultAsync(s=>s.TenantId==tenant);if(subscription!=null&&(subscription.State=="Suspended"||subscription.EndsAt<DateTimeOffset.UtcNow))throw new AccessDeniedException();if(new[]{"studio","service","intelligence"}.Contains(module)&&subscription!=null&&!subscription.Features.Contains(module))throw new AccessDeniedException();var brand=await db.Set<TenantBrand>().AsNoTracking().SingleOrDefaultAsync(b=>b.TenantId==tenant);if(brand!=null&&Modules.Contains(module)&&!brand.Modules.Contains(module))throw new DomainException("This society has disabled the "+module+" module");}
 public static async Task<bool> WorkAllowed(AppDb db,Guid tenant,string module){if(!await db.Tenants.AnyAsync(t=>t.Id==tenant&&t.Status=="Active"))return false;var plan=await db.Set<TenantSubscription>().AsNoTracking().SingleOrDefaultAsync(s=>s.TenantId==tenant);if(plan!=null&&(plan.State=="Suspended"||plan.EndsAt<DateTimeOffset.UtcNow||new[]{"studio","service","intelligence"}.Contains(module)&&!plan.Features.Contains(module)))return false;var brand=await db.Set<TenantBrand>().AsNoTracking().SingleOrDefaultAsync(b=>b.TenantId==tenant);return brand==null||brand.Modules.Contains(module);}
 public async Task<bool> Verify(TenantDomain domain,CancellationToken ct){using var client=clients.CreateClient("domains");client.Timeout=TimeSpan.FromSeconds(15);client.DefaultRequestHeaders.Accept.ParseAdd("application/dns-json");var name="_assemblia."+domain.Host;using var response=await client.GetAsync("https://cloudflare-dns.com/dns-query?name="+Uri.EscapeDataString(name)+"&type=TXT",ct);if(!response.IsSuccessStatusCode)return false;using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));if(!doc.RootElement.TryGetProperty("Answer",out var answers))return false;return answers.EnumerateArray().Any(a=>a.GetProperty("type").GetInt32()==16&&a.GetProperty("name").GetString()?.TrimEnd('.').Equals(name,StringComparison.OrdinalIgnoreCase)==true&&a.GetProperty("data").GetString()?.Replace("\"","").Replace(" ","")=="assemblia-verification="+domain.Challenge);}
 public async Task<object> Readiness(Guid tenant){var entities=await db.Set<FinancialEntity>().CountAsync(e=>e.TenantId==tenant);var keys=config["DataProtection:KeyPath"];var backup=config["Operations:LastVerifiedRestoreAt"];return new{environment=env.EnvironmentName,productionReady=false,gates=new[]{new{gate="Database connectivity",state=await db.Database.CanConnectAsync()?"Pass":"Blocked",detail="Current runtime connectivity only"},new{gate="Financial launch integrations",state=entities==0?"Not configured":"Blocked",detail="Live/sandbox receiving and settlement cycles require explicit verification"},new{gate="Persistent encrypted keys",state=string.IsNullOrWhiteSpace(keys)||string.IsNullOrWhiteSpace(config["DataProtection:CertificatePath"])?"Blocked":"Configured",detail="Certificate/key escrow, decryption and key-ring recovery require an actual deployment drill"},new{gate="Backup restore",state=string.IsNullOrWhiteSpace(backup)?"Blocked":"Operator evidence configured",detail=backup??"Run and inspect a real restore drill"},new{gate="TLS and verified domains",state="Blocked",detail="Requires intended staging/production infrastructure"},new{gate="Independent security/load acceptance",state="Blocked",detail="Local automated results do not certify production security or SLA"}}};}
}
public static class PlatformEndpoints {
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/branding").RequireAuthorization();
  t.MapGet("",async(Guid tenant,AppDb db,Access a)=>{await a.Member(tenant);return await db.Set<TenantBrand>().SingleAsync(b=>b.TenantId==tenant);});
  t.MapPut("",async(Guid tenant,TenantBrand r,AppDb db,Access a)=>{await a.Require(tenant,"branding.manage");if(r.DisplayName.Length>160||r.LoginTitle.Length>240||r.ChapterTerm.Length is <2 or >40||r.RegionTerm.Length is <2 or >40||r.Language.Length is <2 or >12||!Regex.IsMatch(r.PrimaryColor,"^#[0-9a-fA-F]{6}$")||!FinanceService.Currencies.ContainsKey(r.Currency)||r.Modules.Any(m=>!PlatformPolicy.Modules.Contains(m)))throw new DomainException("Check branding, terminology, locale, currency and enabled modules");try{TimeZoneInfo.FindSystemTimeZoneById(r.TimeZone);}catch(TimeZoneNotFoundException){throw new DomainException("Choose a recognized time zone");}foreach(var id in new[]{r.LogoId,r.FaviconId}.Where(id=>id!=null))if(!await db.Assets.AnyAsync(x=>x.TenantId==tenant&&x.Id==id))throw new DomainException("Brand images must be uploaded assets owned by this society");var x=await db.Set<TenantBrand>().SingleAsync(b=>b.TenantId==tenant);if(x.Revision!=r.Revision)return Results.Conflict();x.DisplayName=r.DisplayName;x.PrimaryColor=r.PrimaryColor;x.LoginTitle=r.LoginTitle;x.ChapterTerm=r.ChapterTerm;x.RegionTerm=r.RegionTerm;x.LogoId=r.LogoId;x.FaviconId=r.FaviconId;x.Language=r.Language;x.TimeZone=r.TimeZone;x.Currency=r.Currency;x.Modules=r.Modules.Distinct().ToArray();x.Revision++;var society=await db.Tenants.SingleAsync(s=>s.Id==tenant);var profile=MembershipService.Json(society.Profile);profile["displayName"]=x.DisplayName;profile["brandColor"]=x.PrimaryColor;profile["chapterTerm"]=x.ChapterTerm;profile["regionTerm"]=x.RegionTerm;if(x.LogoId!=null)profile["logoUrl"]=$"/api/v1/branding/assets/{tenant}/{x.LogoId}";society.Profile=profile.ToJsonString();a.Audit(tenant,"branding.updated",x.Id);await db.SaveChangesAsync();return Results.Ok(x);});
  t.MapGet("/domains",async(Guid tenant,AppDb db,Access a)=>{await a.Require(tenant,"branding.manage");return await db.Set<TenantDomain>().Where(d=>d.TenantId==tenant).ToListAsync();});
  t.MapPost("/domains",async(Guid tenant,DomainWrite r,AppDb db,Access a)=>{await a.Require(tenant,"branding.manage");var host=PlatformPolicy.Host(r.Host);if(await db.Set<TenantDomain>().AnyAsync(d=>d.Host==host))throw new DomainException("This hostname is already claimed; ownership changes require an authorized transfer process");var domain=new TenantDomain{TenantId=tenant,Host=host,Challenge=CommunityService.Token()};db.Add(domain);a.Audit(tenant,"domain.claim.requested",domain.Id,new{host});await db.SaveChangesAsync();return Results.Ok(new{domain.Id,domain.Host,domain.Status,txtName="_assemblia."+host,txtValue="assemblia-verification="+domain.Challenge});});
  t.MapPost("/domains/{id:guid}/verify",async(Guid tenant,Guid id,AppDb db,Access a,PlatformPolicy policy,CancellationToken ct)=>{await a.Require(tenant,"branding.manage");var domain=await db.Set<TenantDomain>().SingleOrDefaultAsync(d=>d.TenantId==tenant&&d.Id==id)??throw new AccessDeniedException();if(!await policy.Verify(domain,ct))throw new DomainException("The exact DNS TXT ownership proof was not found. TLS/proxy setup remains separate.");domain.Status="Verified";domain.VerifiedAt=DateTimeOffset.UtcNow;a.Audit(tenant,"domain.ownership.verified",id);await db.SaveChangesAsync();return Results.Ok(new{domain.Id,domain.Host,domain.Status,domain.VerifiedAt});});
  t.MapGet("/readiness",async(Guid tenant,Access a,PlatformPolicy p)=>{await a.Require(tenant,"settings.manage");return await p.Readiness(tenant);});
  api.MapGet("/branding/resolve",async(Guid? society,HttpContext context,PlatformPolicy policy,AppDb db)=>{var domain=await policy.Resolve(context.Request.Host.Host);var tenant=domain?.TenantId??society;if(tenant==null)return Results.Ok(new{tenantId=(Guid?)null,displayName="Assemblia",loginTitle="Welcome to your community",primaryColor="#117d72",chapterTerm="Chapter",regionTerm="Region"});var brand=await db.Set<TenantBrand>().AsNoTracking().SingleOrDefaultAsync(b=>b.TenantId==tenant&&db.Tenants.Any(t=>t.Id==b.TenantId&&t.Status=="Active"));if(brand==null)return Results.NotFound();var name=await db.Tenants.Where(t=>t.Id==tenant).Select(t=>t.Name).SingleAsync();return Results.Ok(new{tenantId=tenant,displayName=brand.DisplayName==""?name:brand.DisplayName,brand.LoginTitle,brand.PrimaryColor,brand.ChapterTerm,brand.RegionTerm,brand.Language,brand.TimeZone,brand.Currency,logo=brand.LogoId==null?null:$"/api/v1/branding/assets/{tenant}/{brand.LogoId}",favicon=brand.FaviconId==null?null:$"/api/v1/branding/assets/{tenant}/{brand.FaviconId}"});}).RequireRateLimiting("verify");
  api.MapGet("/branding/assets/{tenant:guid}/{id:guid}",async(Guid tenant,Guid id,AppDb db,IObjectStore store)=>{if(!await db.Set<TenantBrand>().AnyAsync(b=>b.TenantId==tenant&&(b.LogoId==id||b.FaviconId==id)&&db.Tenants.Any(t=>t.Id==tenant&&t.Status=="Active")))return Results.NotFound();return Results.File(store.Open(tenant,id),"image/png");}).RequireRateLimiting("verify");
  var platform=api.MapGroup("/platform").RequireAuthorization();platform.AddEndpointFilter(async(ctx,next)=>{await ctx.HttpContext.RequestServices.GetRequiredService<Access>().RequirePlatform();return await next(ctx);});
  platform.MapGet("/tenants",async(string? search,int? page,AppDb db)=>{var q=db.Tenants.AsNoTracking();if(!string.IsNullOrWhiteSpace(search))q=q.Where(t=>EF.Functions.ILike(t.Name,"%"+search+"%"));return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderBy(t=>t.Name).ThenBy(t=>t.Id).Skip(Math.Max(0,(page??1)-1)*50).Take(50).Select(t=>new{t.Id,t.Name,t.Status,t.CreatedAt,chapters=db.Units.Count(u=>u.TenantId==t.Id&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")),activeMemberships=db.Memberships.Count(m=>m.TenantId==t.Id&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow)),storageBytes=db.Assets.Where(a=>a.TenantId==t.Id).Sum(a=>a.Length)+db.MemberDocuments.Where(d=>d.TenantId==t.Id).Sum(d=>d.Length)+db.Set<StudioAsset>().Where(a=>a.TenantId==t.Id).Sum(a=>a.Length)+db.Set<FinanceFile>().Where(f=>f.TenantId==t.Id).Sum(f=>f.Length),messages=db.Outbox.Count(o=>o.TenantId==t.Id),aiQueries=db.Set<AssistantQuery>().Count(q=>q.TenantId==t.Id),aiTokens=db.Set<AssistantQuery>().Where(q=>q.TenantId==t.Id).Sum(q=>(long)q.InputTokens+q.OutputTokens),subscription=db.Set<TenantSubscription>().Where(s=>s.TenantId==t.Id).Select(s=>new{s.Plan,s.State,s.ChapterLimit,s.MembershipLimit,s.StorageLimit,s.Features,s.EndsAt,s.Revision}).SingleOrDefault(),integrationAccounts=db.Set<CommunicationAccount>().Count(c=>c.TenantId==t.Id),verifiedPaymentConnections=db.Set<PaymentConnection>().Count(p=>p.TenantId==t.Id&&p.Verified&&p.Enabled)}).ToListAsync(),storageBasis="Recorded asset/document metadata; generated credential/job artifacts are not included until storage inventory accounting is enabled"});});
  platform.MapPost("/tenants/{tenant:guid}/status",async(Guid tenant,TenantStatusWrite r,Access a,AppDb db)=>{if(r.Status is not("Active" or "Suspended")||r.Reason.Length is <3 or >2000)throw new DomainException("Choose activation/suspension and record a reason");var society=await db.Tenants.SingleOrDefaultAsync(t=>t.Id==tenant)??throw new DomainException("Society not found");society.Status=r.Status;a.Audit(Guid.Empty,"platform.tenant.status.changed",tenant,new{r.Status,r.Reason});await db.SaveChangesAsync();return Results.Ok(new{society.Id,society.Status});});
  platform.MapPut("/tenants/{tenant:guid}/subscription",async(Guid tenant,SubscriptionWrite r,Access a,AppDb db)=>{if(r.Plan.Length is <2 or >80||r.State is not("Trial" or "Active" or "Suspended")||r.ChapterLimit is <1 or >1000000||r.MembershipLimit is <1 or >10000000||r.StorageLimit<1048576||r.Features.Any(f=>!new[]{"studio","service","intelligence","assistant"}.Contains(f)))throw new DomainException("Check plan metadata, limits and feature entitlements");var plan=await db.Set<TenantSubscription>().SingleOrDefaultAsync(s=>s.TenantId==tenant)??throw new DomainException("Society plan not found");if(plan.Revision!=r.Revision)return Results.Conflict();plan.Plan=r.Plan;plan.State=r.State;plan.ChapterLimit=r.ChapterLimit;plan.MembershipLimit=r.MembershipLimit;plan.StorageLimit=r.StorageLimit;plan.Features=r.Features.Distinct().ToArray();plan.EndsAt=r.EndsAt;plan.Revision++;a.Audit(Guid.Empty,"platform.subscription.changed",tenant,new{r.Plan,r.State,r.Features});await db.SaveChangesAsync();return Results.Ok(plan);});
  platform.MapGet("/tenants/{tenant:guid}/storage",(Guid tenant,IObjectStore store)=>store.Usage(tenant));
  platform.MapGet("/audit",async(int? page,AppDb db)=>await db.Audits.Where(a=>a.TenantId==Guid.Empty).OrderByDescending(a=>a.At).Skip(Math.Max(0,(page??1)-1)*50).Take(50).Select(a=>new{a.Id,a.ActorId,a.Action,a.ResourceId,a.Details,a.At}).ToListAsync());
  platform.MapGet("/health",async(AppDb db,IHostEnvironment env)=>new{environment=env.EnvironmentName,database=await db.Database.CanConnectAsync(),pendingMigrations=(await db.Database.GetPendingMigrationsAsync()).ToArray(),studioQueue=await db.Set<StudioJob>().CountAsync(j=>j.State=="Queued"),failedStudioJobs=await db.Set<StudioJob>().CountAsync(j=>j.State=="Failed"),outboxQueue=await db.Outbox.CountAsync(o=>o.Status=="Queued"),deadLetters=await db.Outbox.CountAsync(o=>o.Status=="Failed"),workingSetBytes=Environment.WorkingSet,processUptimeSeconds=(DateTimeOffset.UtcNow-System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime()).TotalSeconds});
 }
}
